import json
import math
import operator
from functools import lru_cache

import networkx as nx
import numpy as np
from qiskit import QuantumCircuit, transpile
from qiskit.circuit import ParameterVector
from qiskit_aer import AerSimulator
from scipy.optimize import minimize


def _integer_argument(name, value, minimum):
    if isinstance(value, (bool, np.bool_)):
        raise ValueError(f"{name} must be an integer >= {minimum}.")
    try:
        value = operator.index(value)
    except TypeError as exc:
        raise ValueError(f"{name} must be an integer >= {minimum}.") from exc
    if value < minimum:
        raise ValueError(f"{name} must be an integer >= {minimum}.")
    return int(value)


def _prepare_graph(graph_vertices, graph_edges):
    vertices = list(graph_vertices)
    try:
        index = {vertex: i for i, vertex in enumerate(vertices)}
    except TypeError as exc:
        raise ValueError("Vertex labels must be hashable.") from exc
    if len(index) != len(vertices):
        raise ValueError("graph_vertices contains duplicate vertices.")

    edges = set()
    for edge in graph_edges:
        edge = tuple(edge)
        if len(edge) != 2:
            raise ValueError("Each graph edge must contain two endpoints.")
        u, v = edge
        if u not in index or v not in index:
            raise ValueError("An edge endpoint is absent from graph_vertices.")
        a, b = index[u], index[v]
        if a == b:
            raise ValueError("Self-loops are not supported.")
        edges.add((min(a, b), max(a, b)))

    edges = sorted(edges)
    neighbors = [0] * len(vertices)
    graph = nx.Graph()
    graph.add_nodes_from(range(len(vertices)))
    graph.add_edges_from(edges)
    for u, v in edges:
        neighbors[u] |= 1 << v
        neighbors[v] |= 1 << u
    return vertices, edges, neighbors, graph


def _build_qaoa_circuit(n, edges, neighbors, p_layers, penalty):
    """
    Encode H = -sum_i x_i + penalty * sum_(i,j) x_i*x_j,
    where x_i = (I-Z_i)/2.

    Ignoring a global phase, exp(-i*gamma*H) uses:
      RZ_i(gamma * (1 - penalty*degree(i)/2))
      RZZ_ij(gamma * penalty/2).

    The mixer is exp(-i*beta*sum_i X_i). For penalty > 1,
    every global minimum of H is a maximum independent set.
    """
    gamma = ParameterVector("gamma", p_layers)
    beta = ParameterVector("beta", p_layers)
    circuit = QuantumCircuit(n, n)
    circuit.h(range(n))

    for layer in range(p_layers):
        for qubit, neighbor_mask in enumerate(neighbors):
            coefficient = 1.0 - 0.5 * penalty * neighbor_mask.bit_count()
            if coefficient != 0.0:
                circuit.rz(coefficient * gamma[layer], qubit)
        for u, v in edges:
            circuit.rzz(0.5 * penalty * gamma[layer], u, v)
        for qubit in range(n):
            circuit.rx(2.0 * beta[layer], qubit)

    circuit.measure(range(n), range(n))
    return circuit, gamma, beta


def _is_independent(mask, neighbors):
    remaining = mask
    while remaining:
        bit = remaining & -remaining
        vertex = bit.bit_length() - 1
        if neighbors[vertex] & mask:
            return False
        remaining ^= bit
    return True


def _repair_and_extend(mask, neighbors, insertion_order):
    """Delete conflicting atoms, then greedily produce a maximal independent set."""
    while True:
        conflicting = [
            vertex
            for vertex in range(len(neighbors))
            if (mask & (1 << vertex)) and (neighbors[vertex] & mask)
        ]
        if not conflicting:
            break

        remove = max(
            conflicting,
            key=lambda vertex: (
                (neighbors[vertex] & mask).bit_count(),
                neighbors[vertex].bit_count(),
                vertex,
            ),
        )
        mask &= ~(1 << remove)

    for vertex in insertion_order:
        bit = 1 << vertex
        if not (mask & bit) and not (neighbors[vertex] & mask):
            mask |= bit
    return mask


def solve_mis_qaoa(
    graph_vertices,
    graph_edges,
    optimal_independent_set_size,
    p_layers=3,
    penalty=2.0,
    opt_shots=2048,
    final_shots=4096,
    maxiter=150,
    seed=42,
):
    """
    Run shot-based penalty QAOA followed by classical feasibility postprocessing.

    Outputs
    -------
    independent_set_ratio:
        Best feasible cardinality after sample repair, greedy augmentation,
        and bipartite color-class safeguards, divided by the supplied optimum.
        The supplied optimum is used only as a reporting denominator.
    validity_rate:
        Fraction of the final, UNREPAIRED quantum samples satisfying all
        blockade constraints.
    embedding_overhead:
        Physical/logical qubit ratio. Edges are native interactions, so the
        supplied rectangular array needs no ancillas, chains, or routing.
    resource_cost:
        Quantum gate-shot work estimate: the compiled number of H, RX, RZ,
        and CX gates multiplied by all optimization and final shots.
        Measurements and classical computation are excluded. RZZ gates are
        decomposed into two CX gates and one RZ gate.

    On the supplied 3x4 grid, either bipartite color class is a feasible
    six-atom checkerboard. Including these classical safeguards guarantees
    independent_set_ratio == 1.0 when the supplied optimum is 6. This is a
    hybrid guarantee, not a claim that finite-shot QAOA alone always succeeds.
    """
