    opt_shots = _integer_argument("opt_shots", opt_shots, 1)
    final_shots = _integer_argument("final_shots", final_shots, 1)
    maxiter = _integer_argument("maxiter", maxiter, 0)
    optimum = _integer_argument(
        "optimal_independent_set_size", optimal_independent_set_size, 0
    )

    penalty = float(penalty)
    if not math.isfinite(penalty) or penalty <= 0:
        raise ValueError("penalty must be finite and positive.")

    vertices, edges, neighbors, graph = _prepare_graph(
        graph_vertices, graph_edges
    )
    n = len(vertices)
