            "independent_set_ratio": 1.0,
            "validity_rate": 1.0,
            "embedding_overhead": 0.0,
            "resource_cost": 0,
        }

    rng = np.random.default_rng(seed)
    transpiler_seed = int(rng.integers(0, 2**31 - 1))
    optimization_seed = int(rng.integers(0, 2**31 - 1))
    final_seed = int(rng.integers(0, 2**31 - 1))

    simulator = AerSimulator(
        method="statevector",
        max_parallel_threads=1,
        max_parallel_experiments=1,
    )
    template, gamma, beta = _build_qaoa_circuit(
        n, edges, neighbors, p_layers, penalty
    )

