    # all-to-all hardware connectivity or additional physical qubits is needed.
    compiled = transpile(
        template,
        basis_gates=["h", "rx", "rz", "cx"],
        optimization_level=1,
        seed_transpiler=transpiler_seed,
    )
    unitary_gates_per_shot = sum(
        int(count)
        for name, count in compiled.count_ops().items()
        if name not in {"measure", "barrier", "delay", "reset"}
    )

    total_shots = 0

    def sample(parameters, shots, simulator_seed):
        nonlocal total_shots
        binding = {
            gamma[layer]: float(parameters[layer])
            for layer in range(p_layers)
        }
        binding.update(
            {
                beta[layer]: float(parameters[p_layers + layer])
                for layer in range(p_layers)
            }
        )
        bound = compiled.assign_parameters(binding, inplace=False)
        result = simulator.run(
            bound,
            shots=shots,
            seed_simulator=simulator_seed,
        ).result()
        if not result.success:
            raise RuntimeError(f"Aer simulation failed: {result.status}")

        counts = result.get_counts(0)
        # Qiskit's rightmost classical bit corresponds to qubit zero.
        histogram = {
            int(bitstring.replace(" ", ""), 2): int(count)
            for bitstring, count in counts.items()
        }
        if sum(histogram.values()) != shots:
            raise RuntimeError("The simulator returned an unexpected shot count.")
        total_shots += shots
        return histogram

    edge_masks = tuple((1 << u) | (1 << v) for u, v in edges)

    @lru_cache(maxsize=65536)
    def classical_energy(mask):
        violations = sum(
            (mask & edge_mask) == edge_mask for edge_mask in edge_masks
        )
        return -float(mask.bit_count()) + penalty * violations

    initial_parameters = np.concatenate(
        [
            np.linspace(0.2, 0.8, p_layers) / max(1.0, penalty),
            -np.linspace(0.6, 0.2, p_layers),
        ]
    )
    best_parameters = initial_parameters.copy()
    best_energy = math.inf

    def objective(parameters):
        nonlocal best_parameters, best_energy
        # A common simulator seed makes repeated evaluations reproducible
        # and reduces unnecessary variation in the shot-based objective.
        histogram = sample(parameters, opt_shots, optimization_seed)
        energy = sum(
            count * classical_energy(mask)
            for mask, count in histogram.items()
        ) / opt_shots

        if energy < best_energy:
            best_energy = float(energy)
            best_parameters = np.asarray(parameters, dtype=float).copy()
        return float(energy)

    if maxiter > 0:
        minimize(
            objective,
            initial_parameters,
            method="COBYLA",
            options={
                "maxiter": maxiter,
                "rhobeg": 0.35,
                "tol": 1e-3,
                "disp": False,
            },
        )

    # Use an independent seed for the reported raw sampling statistics.
    final_histogram = sample(best_parameters, final_shots, final_seed)
    valid_shots = sum(
        count
        for mask, count in final_histogram.items()
        if _is_independent(mask, neighbors)
    )

