    low_degree_order = tuple(
        sorted(range(n), key=lambda vertex: (neighbors[vertex].bit_count(), vertex))
    )
    insertion_orders = (
        natural_order,
        tuple(reversed(natural_order)),
        low_degree_order,
    )

    best_mask = 0

    def consider(mask):
        nonlocal best_mask
        if not _is_independent(mask, neighbors):
            raise RuntimeError("Postprocessing produced an invalid independent set.")
