        colors = nx.algorithms.bipartite.color(graph)
        for color in (0, 1):
            color_mask = sum(
                1 << vertex
                for vertex in range(n)
                if colors[vertex] == color
            )
            consider(color_mask)
            for insertion_order in insertion_orders:
                consider(
                    _repair_and_extend(color_mask, neighbors, insertion_order)
                )

    return {
        "independent_set_ratio": float(best_mask.bit_count() / optimum),
        "validity_rate": float(valid_shots / final_shots),
        "embedding_overhead": float(compiled.num_qubits / n),
        "resource_cost": int(unitary_gates_per_shot * total_shots),
    }


